class Solution:

	def dfs(self, i, j, visited, grid):
		n = len(grid)
		m = len(grid[0])
		if i >= n or j >= m or i < 0 or (j < 0):
			return False
		if grid[i][j] == 0:
			return False
		if visited[i][j] != 0:
			return False
		if grid[i][j] == 2:
			return True
		if visited[i][j] == 0:
			visited[i][j] = 1
			d1 = self.dfs(i, j + 1, visited, grid)
			d2 = self.dfs(i, j - 1, visited, grid)
			d3 = self.dfs(i + 1, j, visited, grid)
			d4 = self.dfs(i - 1, j, visited, grid)
		return d1 or d2 or d3 or d4

	def is_Possible(self, grid):
		n = len(grid)
		m = len(grid[0])
		visited = [[0 for j in range(m)] for i in range(n)]
		for i in range(n):
			for j in range(m):
				if grid[i][j] == 1:
					if self.dfs(i, j, visited, grid) == True:
						return True
		return False
